def card(task, wd):
    W, H = (320, 180)
    yy, xx = np.mgrid[:H, :W]

    def blob(cx, cy, r, t, seed):
        th = np.arctan2(yy - cy, xx - cx)
        rr = r * (1 + 0.12 * perlin2(np.cos(th) * 1.5 + t, np.sin(th) * 1.5 + seed, seed))
        return (np.hypot(xx - cx, yy - cy) < rr).astype(float)

    def frame(t, gooey=True):
        d = 60 * (1 - float(in_out_cubic(np.clip(t / 0.8, 0, 1))))
        al = np.maximum(blob(160 - 40 - d, 90, 34, t, 1), blob(160 + 40 + d, 90, 34, t, 2))
        if gooey:
            al = goo(al, 10)
        return np.repeat((al * 255)[..., None], 3, 2)
    ts = np.arange(0, 1.0, 1 / 30)
    vid = video(wd / 'liquid.mp4', [frame(t) for t in ts])
    fr = vread(vid, W, H)
    comps = [label(f.max(-1) > 128)[1] for f in fr]
    plain = label(frame(0.95, gooey=False).max(-1) > 128)[1]
    edge_var = float(np.abs(frame(0.2) - frame(0.5)).mean())
    return ([check('blobs separate at the start (2 parts)', comps[0] == 2, comps[0], 2), check('gooey filter merges them when close (1 part)', comps[-1] == 1, comps[-1], 1), check('noise keeps the outline moving', edge_var > 1, edge_var, '>1'), check('negative control: without the goo filter they stay apart', plain == 2, plain, 2)], [vid])

def card(task, wd):
    cols, rows, C = (8, 5, 40)
    W, H = (cols * C, rows * C)
    pal = [hexc('#d6341f'), hexc('#e9c634'), hexc('#2135bc'), hexc('#111111')]
    glyphs = ['quarter', 'triangle', 'bar', 'circle']

    def cell(g, col, rot):
        im = Image.new('RGB', (C, C), (243, 234, 216))
        d = ImageDraw.Draw(im)
        if g == 'quarter':
            d.pieslice([-C, -C, C, C], 0, 90, fill=tuple((int(v) for v in col)))
        elif g == 'triangle':
            d.polygon([(0, 0), (C, 0), (0, C)], fill=tuple((int(v) for v in col)))
        elif g == 'bar':
            d.rectangle([0, C * 0.35, C, C * 0.65], fill=tuple((int(v) for v in col)))
        else:
            d.ellipse([C * 0.15, C * 0.15, C * 0.85, C * 0.85], fill=tuple((int(v) for v in col)))
        return np.asarray(im.rotate(-90 * rot)).astype(float)

    def step_of(x, y, t, wave=True):
        return int(math.floor(max(0, t * 4 - ((x + y) * 0.3 if wave else 0))))

    def frame(t, wave=True):
        a = np.zeros((H, W, 3))
        for y in range(rows):
            for x in range(cols):
                s_ = step_of(x, y, t, wave)
                a[y * C:(y + 1) * C, x * C:(x + 1) * C] = cell(glyphs[(x + y + s_) % 4], pal[(x * 3 + y + s_) % 4], s_)
        return a
    ts = np.arange(0, 2.0, 1 / 15)
    vid = video(wd / 'bauhaus.mp4', [frame(t) for t in ts], 15)
    fr = vread(vid, W, H)
    change = lambda f0, f1, x, y: float(np.abs(f1[y * C:(y + 1) * C, x * C:(x + 1) * C] - f0[y * C:(y + 1) * C, x * C:(x + 1) * C]).mean()) > 5

    def firsts(frs):
        return {(x, y): next((i for i in range(1, len(frs)) if change(frs[i - 1], frs[i], x, y)), None) for x, y in [(0, 0), (3, 1), (7, 4)]}
    first = firsts(fr)
    order = first[0, 0] < first[3, 1] < first[7, 4]
    flat = firsts([frame(t, wave=False) for t in ts[:12]])
    flat_order = flat[0, 0] is not None and flat[0, 0] < flat[3, 1] < flat[7, 4]
    exp = {k: math.ceil(((k[0] + k[1]) * 0.3 + 1) / 4 * 15) for k in first}
    first = {'%d,%d' % k: v for k, v in first.items()}
    exp = {'%d,%d' % k: v for k, v in exp.items()}
    pal_ok = len({tuple(v) for v in np.round(fr[-1].reshape(-1, 3) / 8).astype(int)}) <= 12
    return ([check('swap wave travels diagonally (corner first)', order, first, '(0,0)<(3,1)<(7,4)'), check('first swap frame matches step = floor(t*4 - d*.3) (+-1 frame)', all((abs(first[k] - exp[k]) <= 1 for k in first)), first, exp), check('4-5 colour palette on cream', pal_ok, pal_ok, True), check('negative control: without the distance delay all cells swap together', not flat_order, {'%d,%d' % k: v for k, v in flat.items()}, 'same frame')], [vid])
